{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 노외주차장에서 일반 승용차로 버스 환승 시, 녹색교통지역 안이면 환승 50% 할인 적용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제4호는 녹색교통지역을 제외한 지역의 노외주차장에서 버스·지하철 환승목적으로 주차하고 주차관리자동화시스템 또는 출차 시 정산기로 확인되면 주차요금의 100분의 50을 할인한다고 정하고 있다. 따라서 녹색교통지역 안의 노외주차장은 이 감면 규정의 적용 대상에서 제외되므로, 환승 사실이 정산기에서 확인되더라도 환승 50% 할인은 적용되지 않는다.",
          "b_ids": "주차장:제7조제1항제4호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
